def db_connect() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH, timeout=20)
    conn.row_factory = sqlite3.Row
    return conn


def init_db() -> None:
    with db_connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS signals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL,
            symbol TEXT NOT NULL,
            side TEXT NOT NULL,
            payload TEXT NOT NULL,
            dedupe_key TEXT NOT NULL UNIQUE,
            delivered INTEGER NOT NULL DEFAULT 0
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS strategy_calls_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL,
            day TEXT NOT NULL,
            time_ist TEXT NOT NULL,
            strategy_header TEXT NOT NULL,
            symbol TEXT NOT NULL,
            side TEXT NOT NULL,
            entry_price REAL NOT NULL,
            stop_price REAL NOT NULL,
            target_price REAL NOT NULL,
            stop_pct REAL NOT NULL,
            target_pct REAL NOT NULL,
            trailing_stop INTEGER NOT NULL DEFAULT 0,
            profit_lock_trig_pct REAL NOT NULL DEFAULT 0.0,
            conviction REAL NOT NULL DEFAULT 0.0,
            status TEXT NOT NULL DEFAULT 'OPEN',
            outcome TEXT DEFAULT NULL,
            exit_price REAL DEFAULT NULL,
            net_ret_pct REAL DEFAULT NULL,
            mfe_pct REAL DEFAULT 0.0,
            mae_pct REAL DEFAULT 0.0,
            payload TEXT NOT NULL,
            dedupe_key TEXT NOT NULL UNIQUE
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS app_state (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )""")
        conn.commit()


def state_get(key: str, default: Optional[str] = None) -> Optional[str]:
    with db_connect() as conn:
        row = conn.execute("SELECT value FROM app_state WHERE key=?", (key,)).fetchone()
        return row["value"] if row else default


def state_set(key: str, value: str) -> None:
    with db_connect() as conn:
        conn.execute("INSERT INTO app_state(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, value))
        conn.commit()


def reset_today_quota() -> None:
    day = datetime.now(TZ).strftime("%Y-%m-%d")
    with db_connect() as conn:
        conn.execute("DELETE FROM signals WHERE created_at LIKE ?", (day + "%",))
        conn.execute("DELETE FROM strategy_calls_log WHERE day=?", (day,))
        conn.execute("DELETE FROM app_state WHERE key IN ('heartbeat_day','digest_day','warned_low_coverage')")
        conn.commit()
    LOG.info("Cleared today's quota and state for %s", day)


