def load_kronos() -> None:
    global kronos_predictor, kronos_status
    if not CFG["KRONOS_ENABLED"]:
        kronos_status = "disabled"
        return
    if not KRONOS_REPO_DIR.exists():
        kronos_status = "repo_missing"
        return
    sys.path.insert(0, str(KRONOS_REPO_DIR))
    try:
        import torch
        from model import Kronos, KronosTokenizer, KronosPredictor
        torch.set_num_threads(max(1, min(2, os.cpu_count() or 1)))
        tokenizer = KronosTokenizer.from_pretrained(CFG["KRONOS_TOKENIZER"])
        model = Kronos.from_pretrained(CFG["KRONOS_MODEL"])
        kronos_predictor = KronosPredictor(model, tokenizer, device="cpu", max_context=2048)
        kronos_status = "ready:cpu"
        LOG.info("Kronos-mini loaded on CPU")
    except Exception as exc:
        kronos_predictor = None
        kronos_status = "error:" + str(exc)[:240]
        LOG.warning("Kronos initialization skipped: %s", exc)


def fetch_nse_equity_symbols() -> List[str]:
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36",
        "Accept": "text/csv,text/plain,*/*",
        "Referer": "https://www.nseindia.com/",
    }
    resp = requests.get(NSE_EQUITY_CSV, headers=headers, timeout=25)
    resp.raise_for_status()
    df = pd.read_csv(io.StringIO(resp.text))
    cols = {str(c).strip().upper(): c for c in df.columns}
    sym_col = cols.get("SYMBOL")
    series_col = cols.get("SERIES")
    if not sym_col:
        raise ValueError("NSE equity CSV does not contain a SYMBOL column")
    if series_col:
        df = df[df[series_col].astype(str).str.upper().str.strip().eq("EQ")]
    symbols = (
        df[sym_col].astype(str).str.upper().str.strip()
        .loc[lambda s: s.str.fullmatch(r"[A-Z0-9&-](1, 30)")]
        .drop_duplicates().tolist()
    )
    symbols = [s for s in symbols if not s.endswith("-BE") and not s.endswith("-SM")]
    return symbols[:CFG["MAX_EQUITY_UNIVERSE"]]


def extract_ticker_frame(downloaded: pd.DataFrame, ticker: str, single: bool = False) -> pd.DataFrame:
    if downloaded is None or downloaded.empty:
        return pd.DataFrame()
    if isinstance(downloaded.columns, pd.MultiIndex):
        for level in (0, 1):
            try:
                if ticker in downloaded.columns.get_level_values(level):
                    frame = downloaded.xs(ticker, axis=1, level=level, drop_level=True)
                    return frame.dropna(how="all")
            except Exception:
                pass
        return pd.DataFrame()
    if single:
        return downloaded.dropna(how="all")
    return pd.DataFrame()


def download_batch(symbols: List[str], period: str, interval: str) -> Dict[str, pd.DataFrame]:
    tickers = [s + ".NS" for s in symbols]
    if not tickers:
        return {}
    try:
        raw = yf.download(
            tickers=tickers,
            period=period,
            interval=interval,
            group_by="ticker",
            auto_adjust=False,
            actions=False,
            threads=True,
            progress=False,
            timeout=25,
        )
    except Exception as exc:
        LOG.warning("Yahoo batch failed (%s): %s", len(symbols), exc)
        return {s: pd.DataFrame() for s in symbols}
    out: Dict[str, pd.DataFrame] = {}
    for s, ticker in zip(symbols, tickers):
        frame = extract_ticker_frame(raw, ticker, single=(len(tickers) == 1))
        if not frame.empty:
            frame.columns = [str(c).lower().replace(" ", "_") for c in frame.columns]
            expected = ["open", "high", "low", "close", "volume"]
            if all(c in frame.columns for c in expected):
                frame = frame[expected].copy().dropna(subset=["open", "high", "low", "close"])
            else:
                frame = pd.DataFrame()
        out[s] = frame
    return out


def ema(values: Any, period: int) -> float:
    arr = np.asarray(values, dtype=float)
    if len(arr) < period:
        return float("nan")
    alpha = 2.0 / (period + 1.0)
    result = float(np.mean(arr[:period]))
    for x in arr[period:]:
        result = alpha * float(x) + (1.0 - alpha) * result
    return result


def rsi(values: Any, period: int = 14) -> float:
    arr = np.asarray(values, dtype=float)
    if len(arr) <= period:
        return float("nan")
    delta = np.diff(arr)
    gains = np.maximum(delta, 0)
    losses = np.maximum(-delta, 0)
    avg_gain = float(np.mean(gains[:period]))
    avg_loss = float(np.mean(losses[:period]))
    for i in range(period, len(gains)):
        avg_gain = (avg_gain * (period - 1) + float(gains[i])) / period
        avg_loss = (avg_loss * (period - 1) + float(losses[i])) / period
    if avg_loss == 0:
        return 100.0 if avg_gain > 0 else 50.0
    rs = avg_gain / avg_loss
    return 100.0 - 100.0 / (1.0 + rs)


def atr(df: pd.DataFrame, period: int = 14) -> float:
    high = df["high"].astype(float)
    low = df["low"].astype(float)
    close = df["close"].astype(float)
    prev = close.shift(1)
    tr = pd.concat([(high - low).abs(), (high - prev).abs(), (low - prev).abs()], axis=1).max(axis=1)
    value = tr.tail(period).mean()
    return float(value) if pd.notna(value) else float("nan")


def refresh_liquid_universe(force: bool = False) -> Dict[str, Any]:
    if not force and UNIVERSE_CACHE.exists():
        try:
            cached = json.loads(UNIVERSE_CACHE.read_text())
            refreshed = datetime.fromisoformat(cached["refreshed_at"])
            if datetime.now(TZ) - refreshed < timedelta(hours=CFG["UNIVERSE_MAX_AGE_HOURS"]):
                return cached
        except Exception:
            pass

    symbols = fetch_nse_equity_symbols()
    LOG.info("NSE main-board EQ symbols loaded: %d", len(symbols))
    metrics: List[Dict[str, Any]] = []
    batch_size = 60
    for start in range(0, len(symbols), batch_size):
        group = symbols[start:start + batch_size]
        data = download_batch(group, CFG["DAILY_HISTORY_PERIOD"], "1d")
        for symbol in group:
            df = data.get(symbol, pd.DataFrame())
            if df.empty or "close" not in df or "volume" not in df:
                continue
            idx = pd.to_datetime(df.index)
            if idx.tz is not None:
                idx = idx.tz_convert(TZ).tz_localize(None)
            keep = [x.date() < datetime.now(TZ).date() for x in idx]
            hist = df.loc[keep].copy()
            close = pd.to_numeric(hist["close"], errors="coerce").dropna()
            volume = pd.to_numeric(hist["volume"], errors="coerce").reindex(close.index).fillna(0)
            if len(close) < 50:
                continue
            turnover = (close * volume).replace([np.inf, -np.inf], np.nan).dropna()
            if len(turnover) < CFG["LIQUIDITY_LOOKBACK_DAYS"]:
                continue
            avg_turnover = float(turnover.tail(CFG["LIQUIDITY_LOOKBACK_DAYS"]).mean())
            last_price = float(close.iloc[-1])
            e20 = float(ema(close.values, 20))
            e50 = float(ema(close.values, 50))
            prev_close = float(close.iloc[-1])
            if last_price >= CFG["PRICE_FLOOR"] and avg_turnover >= CFG["MIN_AVG_TURNOVER_INR"]:
                metrics.append({
                    "symbol": symbol,
                    "price": last_price,
                    "avg_turnover": avg_turnover,
                    "daily_ema20": e20,
                    "daily_ema50": e50,
                    "previous_close": prev_close,
                })
        time.sleep(0.15)

    metrics.sort(key=lambda x: x["avg_turnover"], reverse=True)
    if not metrics:
        if UNIVERSE_CACHE.exists():
            return json.loads(UNIVERSE_CACHE.read_text())
        raise RuntimeError("No liquid universe was created. Check NSE/Yahoo data access.")

    result = {
        "refreshed_at": datetime.now(TZ).isoformat(),
        "source_symbol_count": len(symbols),
        "eligible_count": len(metrics),
        "scan_symbols": metrics[:CFG["INTRADAY_UNIVERSE_SIZE"]],
    }
    UNIVERSE_CACHE.write_text(json.dumps(result, indent=2))
    return result


def normalize_intraday(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    idx = pd.to_datetime(out.index)
    if idx.tz is None:
        idx = idx.tz_localize(TZ)
    else:
        idx = idx.tz_convert(TZ)
    out.index = idx
    out = out[~out.index.duplicated(keep="last")].sort_index()
    return out


def completed_bars(df: pd.DataFrame, now: datetime) -> pd.DataFrame:
    cutoff = pd.Timestamp(now - timedelta(minutes=5)).tz_convert(TZ)
    return df.loc[df.index <= cutoff].copy()


def same_slot_relative_volume(df: pd.DataFrame, last_idx: pd.Timestamp, min_sessions: int) -> Tuple[float, int]:
    slot = last_idx.strftime("%H:%M")
    today = last_idx.date()
    same_slot = df[df.index.strftime("%H:%M") == slot]
    previous = same_slot[[x.date() < today for x in same_slot.index]].tail(5)
    vals = pd.to_numeric(previous["volume"], errors="coerce").dropna()
    current = float(df.loc[last_idx, "volume"])
    if len(vals) < min_sessions or float(vals.mean()) <= 0:
        return 1.0, int(len(vals))
    return current / float(vals.mean()), int(len(vals))


def session_cumulative_relative_volume(df: pd.DataFrame, last_idx: pd.Timestamp, min_sessions: int) -> Tuple[float, int]:
    today = last_idx.date()
    slot = last_idx.strftime("%H:%M")
    current = df[[x.date() == today and x.strftime("%H:%M") <= slot for x in df.index]]
    current_total = float(current["volume"].astype(float).sum())
    prior_totals: List[float] = []
    prior_dates = sorted({x.date() for x in df.index if x.date() < today})[-5:]
    for session_date in prior_dates:
        session = df[[x.date() == session_date and x.strftime("%H:%M") <= slot for x in df.index]]
        if not session.empty:
            prior_totals.append(float(session["volume"].astype(float).sum()))
    if len(prior_totals) < min_sessions or float(np.mean(prior_totals)) <= 0:
        return 1.0, len(prior_totals)
    return current_total / float(np.mean(prior_totals)), len(prior_totals)


def session_vwap(df: pd.DataFrame) -> float:
    today = df.index[-1].date()
    session = df[[x.date() == today for x in df.index]]
    vol = session["volume"].astype(float).clip(lower=0)
    typical = (session["high"].astype(float) + session["low"].astype(float) + session["close"].astype(float)) / 3.0
    total = float(vol.sum())
    return float((typical * vol).sum() / total) if total > 0 else float("nan")


# ==============================================================================
# PRO INDICATOR ENGINE (GANN, TECH, CANDLE, PATTERN, S/R, VP, FVG, OB)
# ==============================================================================
def compute_gann_sq9(price: float, side: str) -> Tuple[bool, bool]:
    if price <= 0:
        return False, False
    root = math.sqrt(price)
    angle = ((root - math.floor(root)) * 360.0) % 360.0
    cardinal_ok = min(abs(angle - k) for k in range(0, 361, 45)) <= 10.0
    step_90 = math.floor(root * 4.0) / 4.0
    g_sup, g_res = step_90 * step_90, (step_90 + 0.25) ** 2
    sr_ok = ((price - g_sup) / price * 100.0 <= 0.45) if side == "BUY" else ((g_res - price) / price * 100.0 <= 0.45)
    return cardinal_ok, sr_ok


def build_pro_candidate_payload(
    symbol: str,
    df: pd.DataFrame,
    entry_meta: Dict[str, Any],
    prev_close: float,
) -> Optional[Dict[str, Any]]:
    if len(df) < 30:
        return None
    last_idx = df.index[-1]
    t_str = last_idx.strftime("%H:%M")
    if t_str < "09:25" or t_str > "14:45":
        return None

    today_mask = np.array([x.date() == last_idx.date() for x in df.index])
    day_df = df[today_mask]
    prior_df = df[~today_mask]
    if len(day_df) < 2 or prior_df.empty:
        return None

    c = df["close"].astype(float)
    h = df["high"].astype(float)
    l = df["low"].astype(float)
    o = df["open"].astype(float)
    v = df["volume"].astype(float)

    price = float(c.iloc[-1])
    if price < CFG["PRICE_FLOOR"]:
        return None

    ema9 = float(c.ewm(span=9, adjust=False).mean().iloc[-1])
    ema21 = float(c.ewm(span=21, adjust=False).mean().iloc[-1])
    ema50 = float(c.ewm(span=50, adjust=False).mean().iloc[-1])

    atr_v = atr(df, 14)
    if not np.isfinite(atr_v) or atr_v <= 0:
        return None
    atr14_pct = (atr_v / price) * 100.0

    sma20 = float(c.tail(20).mean())
    std20 = float(c.tail(20).std() or 1e-6)
    bb_b = (price - (sma20 - 2.0 * std20)) / (4.0 * std20 + 1e-9)

    low14, high14 = float(l.tail(14).min()), float(h.tail(14).max())
    stoch_k = ((price - low14) / (high14 - low14 + 1e-9)) * 100.0
    will_r = ((high14 - price) / (high14 - low14 + 1e-9)) * -100.0

    tp = (h + l + c) / 3.0
    tp_sma = tp.rolling(20).mean()
    cci20 = float(((tp - tp_sma) / (0.015 * (tp - tp_sma).abs().rolling(20).mean() + 1e-9)).iloc[-1] or 0.0)
    roc10 = float(c.pct_change(10).iloc[-1] * 100.0) if len(c) > 11 else 0.0
    rsi_v = rsi(c.values, 14)
    vwap_v = session_vwap(df)
    vwap_pct = ((price - vwap_v) / (vwap_v + 1e-9)) * 100.0

    obv = (np.sign(c.diff().fillna(0)) * v).cumsum()
    obv_slope = float((obv.diff(5) / (v.rolling(20).mean() * 5.0 + 1e-9)).iloc[-1] or 0.0)

    relvol, slot_n = same_slot_relative_volume(df, last_idx, CFG["MIN_TIME_SLOT_SESSIONS"])
    cum_relvol, _ = session_cumulative_relative_volume(df, last_idx, CFG["MIN_TIME_SLOT_SESSIONS"])

    last_bar = df.iloc[-1]
    prev_bar = df.iloc[-2]
    rng = max(float(last_bar["high"] - last_bar["low"]), 1e-9)
    body = abs(float(last_bar["close"] - last_bar["open"]))
    body_r = body / rng
    avg_body = float((c - o).abs().tail(14).mean() or 1e-6)
    body_x = body / (avg_body + 1e-9)
    uwick = (float(last_bar["high"]) - max(float(last_bar["open"]), float(last_bar["close"]))) / rng
    lwick = (min(float(last_bar["open"]), float(last_bar["close"])) - float(last_bar["low"])) / rng

    day_change = ((price / prev_close) - 1.0) * 100.0
    side = "BUY" if (ema9 >= ema21 and price >= vwap_v) or day_change >= 0 else "SELL"

    # Prior day high/low
    last_prior_date = prior_df.index[-1].date()
    prev_session = prior_df[[x.date() == last_prior_date for x in prior_df.index]]
    pdh = float(prev_session["high"].max()) if not prev_session.empty else float(prior_df["high"].tail(25).max())
    pdl = float(prev_session["low"].min()) if not prev_session.empty else float(prior_df["low"].tail(25).min())
    prev_day_break = "ABOVE_PDH" if price > pdh else ("BELOW_PDL" if price < pdl else "INSIDE")

    # 20-bar support/resistance
    prev20 = df.iloc[-21:-1]
    res20 = float(prev20["high"].max())
    sup20 = float(prev20["low"].min())

    # Volume profile (Session POC, VAH, VAL)
    day_closes = day_df["close"].astype(float)
    poc = float(day_closes.median())
    vah = float(day_closes.quantile(0.75))
    val = float(day_closes.quantile(0.25))
    price_vs_val = "ABOVE_VALUE" if price > vah else ("BELOW_VALUE" if price < val else "INSIDE_VALUE")

    # Candles & Patterns
    candles = []
    if float(last_bar["close"]) > float(last_bar["open"]) and float(prev_bar["close"]) < float(prev_bar["open"]) and float(last_bar["close"]) >= float(prev_bar["open"]):
        candles.append("bullish_engulfing")
    if float(last_bar["close"]) < float(last_bar["open"]) and float(prev_bar["close"]) > float(prev_bar["open"]) and float(last_bar["close"]) <= float(prev_bar["open"]):
        candles.append("bearish_engulfing")
    if float(last_bar["close"]) > float(last_bar["open"]) and body_r >= 0.72:
        candles.append("marubozu_bull")
    if float(last_bar["close"]) < float(last_bar["open"]) and body_r >= 0.72:
        candles.append("marubozu_bear")

    pats = []
    if price > res20:
        pats.append("range_breakout_up")
    if price < sup20:
        pats.append("range_breakdown")
    if ema9 > ema21 > ema50:
        pats.append("uptrend_structure")
        ema_stack = "BULL_STACK"
    elif ema9 < ema21 < ema50:
        pats.append("downtrend_structure")
        ema_stack = "BEAR_STACK"
    else:
        ema_stack = "MIXED"

    # FVG & Order Blocks & Gann
    bull_fvg = bool(len(df) >= 3 and float(df.iloc[-1]["low"]) > float(df.iloc[-3]["high"]))
    bear_fvg = bool(len(df) >= 3 and float(df.iloc[-1]["high"]) < float(df.iloc[-3]["low"]))
    bull_ob = bool(float(prev_bar["close"]) < float(prev_bar["open"]) and float(last_bar["close"]) > float(last_bar["open"]) and body_x >= 1.35)
    bear_ob = bool(float(prev_bar["close"]) > float(prev_bar["open"]) and float(last_bar["close"]) < float(last_bar["open"]) and body_x >= 1.35)
    gann_card, gann_sr = compute_gann_sq9(price, side)

    confirms = {
        "volume_profile": (side == "BUY" and price >= poc) or (side == "SELL" and price <= poc),
        "candles": bool(candles),
        "chart_patterns": (side == "BUY" and "range_breakout_up" in pats) or (side == "SELL" and "range_breakdown" in pats),
        "trend_stack": (side == "BUY" and ema_stack == "BULL_STACK") or (side == "SELL" and ema_stack == "BEAR_STACK"),
        "flow": (side == "BUY" and obv_slope > 0 and vwap_pct > 0) or (side == "SELL" and obv_slope < 0 and vwap_pct < 0),
        "levels": (side == "BUY" and prev_day_break == "ABOVE_PDH") or (side == "SELL" and prev_day_break == "BELOW_PDL") or gann_sr,
        "smart_money": (side == "BUY" and (bull_fvg or bull_ob)) or (side == "SELL" and (bear_fvg or bear_ob)),
    }
    sr_conflict = (
        (side == "BUY" and 0.0 < (res20 - price) / price * 100.0 < 0.18)
        or (side == "SELL" and 0.0 < (price - sup20) / price * 100.0 < 0.18)
    )
    conflicts = {
        "volume_profile": (side == "BUY" and price < val) or (side == "SELL" and price > vah),
        "trend_stack": (side == "BUY" and ema_stack == "BEAR_STACK") or (side == "SELL" and ema_stack == "BULL_STACK"),
        "levels": sr_conflict,
    }
    confluence = sum(1 for v in confirms.values() if v)
    conflict_count = sum(1 for v in conflicts.values() if v)

    window = "BEFORE_10AM" if t_str < "10:00" else ("10AM_TO_1PM" if t_str <= "13:00" else "AFTER_2PM")
    day_turnover = float((day_df["close"].astype(float) * day_df["volume"].astype(float)).sum())
    score = int(min(98, max(50, 50 + confluence * 7 - conflict_count * 10 + (8 if relvol >= 1.5 else 0))))

    payload = {
        "side": side,
        "pro": {
            "volume_profile": {
                "poc": round(poc, 2), "vah": round(vah, 2), "val": round(val, 2),
                "price_vs_value": price_vs_val, "poc_distance_pct": round((price - poc) / price * 100.0, 4),
            },
            "candles": candles,
            "chart_patterns": pats,
            "indicators": {
                "stoch_k": round(stoch_k, 4), "williams_r": round(will_r, 4), "cci20": round(cci20, 4),
                "obv_slope_norm": round(obv_slope, 4), "ema_stack": ema_stack, "roc10_pct": round(roc10, 4),
                "bb_percent_b": round(bb_b, 4), "atr14_pct": round(atr14_pct, 4),
                "price_vs_vwap_pct": round(vwap_pct, 4), "prev_day_break": prev_day_break,
                "rsi14": round(rsi_v, 2), "adx14": 25.0, "mfi14": 55.0,
                "gann_cardinal": gann_card, "gann_sr": gann_sr,
            },
            "anatomy": {
                "body_ratio": round(body_r, 4), "upper_wick_ratio": round(uwick, 4),
                "lower_wick_ratio": round(lwick, 4), "body_x_avg": round(body_x, 4),
            },
            "fvg": {"in_bull_fvg": bull_fvg, "in_bear_fvg": bear_fvg},
            "order_blocks": {"at_bull_ob": bull_ob, "at_bear_ob": bear_ob},
            "confirms": confirms,
            "conflicts": conflicts,
            "confluence": confluence,
            "conflict_count": conflict_count,
        },
        "day_move_pct": round(day_change, 2),
        "relative_volume": round(relvol, 2),
        "cumulative_relative_volume": round(cum_relvol, 2),
        "today_turnover_crore": round(day_turnover / 1e7, 1),
        "avg_daily_turnover_crore": round(float(entry_meta.get("avg_turnover", 0)) / 1e7, 1),
        "candle_time": last_idx.isoformat(),
        "score": score,
    }

    return {
        "day": last_idx.strftime("%Y-%m-%d"),
        "time": t_str,
        "symbol": symbol,
        "side": side,
        "price": round(price, 2),
        "prev_close": round(prev_close, 2),
        "day_change_pct": round(day_change, 2),
        "rsi": round(rsi_v, 1),
        "atr": round(atr_v, 2),
        "vwap": round(vwap_v, 2),
        "breakout_level": round(res20 if side == "BUY" else sup20, 2),
        "relative_volume": round(relvol, 2),
        "cumulative_relative_volume": round(cum_relvol, 2),
        "today_turnover_crore": round(day_turnover / 1e7, 1),
        "avg_daily_turnover_crore": round(float(entry_meta.get("avg_turnover", 0)) / 1e7, 1),
        "candle_time": last_idx.isoformat(),
        "body_ratio": round(body_r, 2),
        "score": score,
        "window": window,
        "payload": payload,
        "forecast": None,
    }


# ==============================================================================
# FEATURE EXTRACTORS & THE 4 STRATEGY EVALUATORS
# ==============================================================================
def extract_live_30d_features(r: dict) -> np.ndarray:
    p = r.get("payload", r)
    pro = p.get("pro", {})
    ind = pro.get("indicators", {})
    vp = pro.get("volume_profile", {})
    anat = pro.get("anatomy", {})
    conf = pro.get("confirms", {})
    pats = set(pro.get("chart_patterns", []))
    cands = set(pro.get("candles", []))

    side_str = r.get("side", p.get("side", "BUY"))
    side = 1.0 if side_str == "BUY" else -1.0
    atr_v = float(ind.get("atr14_pct") or 0.30)
    rvol = min(float(p.get("relative_volume") or 1.0), 20.0)
    stoch = float(ind.get("stoch_k") if ind.get("stoch_k") is not None else 50.0)
    bb_b = float(ind.get("bb_percent_b") if ind.get("bb_percent_b") is not None else 0.50)
    vwap = float(ind.get("price_vs_vwap_pct") or 0.0)
    obv = float(ind.get("obv_slope_norm") or 0.0)
    day_mv = float(p.get("day_move_pct") or 0.0)
    body_r = float(anat.get("body_ratio") if anat.get("body_ratio") is not None else 0.50)
    body_x = min(float(anat.get("body_x_avg") if anat.get("body_x_avg") is not None else 1.0), 5.0)
    uwick = float(anat.get("upper_wick_ratio") if anat.get("upper_wick_ratio") is not None else 0.0)
    lwick = float(anat.get("lower_wick_ratio") if anat.get("lower_wick_ratio") is not None else 0.0)

    adv_wick = uwick if side_str == "BUY" else lwick
    fav_wick = lwick if side_str == "BUY" else uwick
    confluence = float(pro.get("confluence") or 0)
    conflict_count = float(pro.get("conflict_count") or 0)
    window = r.get("window", "10AM_TO_1PM")

    return np.array([
        1.0,
        1.0 if side_str == "SELL" else -1.0,
        atr_v * 2.0,
        rvol / 8.0,
        body_r,
        body_x / 2.5,
        adv_wick * 2.0,
        fav_wick * 2.0,
        (confluence - conflict_count) / 4.0,
        1.0 if vp.get("price_vs_value") == "BELOW_VALUE" and side_str == "SELL" else 0.0,
        1.0 if vp.get("price_vs_value") == "ABOVE_VALUE" and side_str == "BUY" else 0.0,
        1.0 if ind.get("prev_day_break") == "BELOW_PDL" and side_str == "SELL" else 0.0,
        1.0 if ind.get("prev_day_break") == "ABOVE_PDH" and side_str == "BUY" else 0.0,
        1.0 if "range_breakdown" in pats and side_str == "SELL" else 0.0,
        1.0 if "range_breakout_up" in pats and side_str == "BUY" else 0.0,
        1.0 if "inverse_head_shoulders_breakout" in pats else 0.0,
        1.0 if "ascending_triangle" in pats else 0.0,
        1.0 if ("bearish_engulfing" in cands or "marubozu_bear" in cands) and side_str == "SELL" else 0.0,
        1.0 if ("bullish_engulfing" in cands or "marubozu_bull" in cands) and side_str == "BUY" else 0.0,
        1.0 if window == "AFTER_2PM" else 0.0,
        1.0 if window == "BEFORE_10AM" else 0.0,
        1.0 if window == "10AM_TO_1PM" else 0.0,
        side * vwap,
        side * obv,
        side * (bb_b - 0.50),
        side * ((stoch - 50.0) / 50.0),
        abs(day_mv) / 3.0,
        1.0 if conf.get("volume_profile") else 0.0,
        1.0 if conf.get("trend_stack") else 0.0,
        1.0 if conf.get("flow") else 0.0,
    ], dtype=float)


def extract_live_34d_features(r: dict) -> np.ndarray:
    base = extract_live_30d_features(r)[1:]  # 29-dim
    p = r.get("payload", r)
    pro = p.get("pro", {})
    ind = pro.get("indicators", {})
    t_str = str(r.get("time", "09:30"))
    parts = t_str.split(":")
    mins = ((int(parts[0]) * 60 + int(parts[1])) - 555.0) / 360.0 if len(parts) >= 2 else 0.0
    score = float(r.get("score", 70)) / 100.0
    rsi_v = float(ind.get("rsi14") or 50.0) / 100.0
    adx_v = float(ind.get("adx14") or 20.0) / 50.0
    mfi_v = float(ind.get("mfi14") or 50.0) / 100.0
    return np.nan_to_num(np.concatenate([base, [mins, score, rsi_v, adx_v, mfi_v]]), nan=0.0, posinf=0.0, neginf=0.0)


# --- HEADER 1: [EARLIER_SETUP] (6-Pillar / Top-Mover Momentum) ---
def evaluate_earlier_setup(r: dict) -> dict:
    p = r.get("payload", r)
    pro = p.get("pro", {})
    ind = pro.get("indicators", {})
    conf = int(pro.get("confluence") or 0)
    rvol = float(p.get("relative_volume") or 0.0)
    atr_pct = float(ind.get("atr14_pct") or 0.25)
    if conf < 4 or rvol < 1.2 or atr_pct < 0.22:
        return {"approved": False, "conviction": 0.0}
    conv = min(0.99, 0.50 + conf * 0.06 + min(rvol, 4.0) * 0.03)
    return {
        "approved": True,
        "strategy_header": "EARLIER_SETUP",
        "conviction": round(conv, 4),
        "target_pct": 2.00,
        "stop_pct": 1.00,
        "trailing_stop": False,
        "profit_lock_trig_pct": 0.0,
        "setup_desc": f"Earlier 6-Pillar Setup (Confluence={conf}/7, RVOL={rvol:.1f}x)",
    }


# --- HEADER 2: [LEARNING_SETUP] (Online Self-Learning Adaptive Engine) ---
def get_learning_weights() -> np.ndarray:
    raw = state_get("learning_weights_30d")
    if raw:
        try:
            arr = np.array(json.loads(raw), dtype=float)
            if len(arr) == 30:
                return arr
        except Exception:
            pass
    return LOCKED_WEIGHTS_V9.copy()


def evaluate_learning_setup(r: dict) -> dict:
    p = r.get("payload", r)
    pro = p.get("pro", {})
    ind = pro.get("indicators", {})
    if int(pro.get("conflict_count") or 0) > 1 or float(ind.get("atr14_pct") or 0.0) < 0.25:
        return {"approved": False, "conviction": 0.0}
    w = get_learning_weights()
    x = extract_live_30d_features(r)
    conv = 1.0 / (1.0 + math.exp(-float(np.clip(np.dot(w, x), -15.0, 15.0))))
    if conv < 0.58:
        return {"approved": False, "conviction": round(conv, 4)}
    return {
        "approved": True,
        "strategy_header": "LEARNING_SETUP",
        "conviction": round(conv, 4),
        "target_pct": 1.50,
        "stop_pct": 1.00,
        "trailing_stop": False,
        "profit_lock_trig_pct": 0.0,
        "setup_desc": f"Online Self-Learning Engine (Conviction={conv:.1%}, Target=+1.5% / SL=-1.0%)",
    }


# --- HEADER 3: [90PCT_SETUP_V9] (90% Version with +2.0% Target & +0.30% Trail) ---
def evaluate_setup_v9(r: dict) -> dict:
    t_str = str(r.get("time", "09:30"))
    if t_str < LOCKED_GENOME_V9["min_time"]:
        return {"approved": False, "conviction": 0.0}
    window = r.get("window", "10AM_TO_1PM")
    if window not in LOCKED_GENOME_V9["allowed_windows"]:
        return {"approved": False, "conviction": 0.0}

    p = r.get("payload", r)
    pro = p.get("pro", {})
    ind = pro.get("indicators", {})
    vp = pro.get("volume_profile", {})
    anat = pro.get("anatomy", {})
    pats = set(pro.get("chart_patterns", []))

    if int(pro.get("conflict_count") or 0) > LOCKED_GENOME_V9["max_conflicts"]:
        return {"approved": False, "conviction": 0.0}
    if float(ind.get("atr14_pct") or 0.0) < LOCKED_GENOME_V9["min_atr"]:
        return {"approved": False, "conviction": 0.0}

    side_str = r.get("side", p.get("side", "BUY"))
    adv_wick = float(anat.get("upper_wick_ratio" if side_str == "BUY" else "lower_wick_ratio") or 0.0)
    if adv_wick > LOCKED_GENOME_V9["max_adv_wick"]:
        return {"approved": False, "conviction": 0.0}

    stoch = float(ind.get("stoch_k") if ind.get("stoch_k") is not None else 50.0)
    bb_b = float(ind.get("bb_percent_b") if ind.get("bb_percent_b") is not None else 0.50)
    if side_str == "BUY" and (stoch > 89.0 and bb_b > 0.97):
        return {"approved": False, "conviction": 0.0}
    if side_str == "SELL" and ((stoch < 10.0 and (bb_b < 0.12 or "uptrend_structure" in pats)) or (bb_b < 0.0 and vp.get("price_vs_value") == "INSIDE_VALUE")):
        return {"approved": False, "conviction": 0.0}

    x = extract_live_30d_features(r)
    x_norm = x / (np.linalg.norm(x) + 1e-8)
    if len(LOCKED_VETO_VECTORS_V9) > 0:
        if float(np.max(LOCKED_VETO_VECTORS_V9 @ x_norm)) >= LOCKED_GENOME_V9["veto_sim_max"]:
            return {"approved": False, "conviction": 0.0}

    conv = 1.0 / (1.0 + math.exp(-float(np.clip(np.dot(LOCKED_WEIGHTS_V9, x), -15.0, 15.0))))
    if conv < LOCKED_GENOME_V9["threshold"]:
        return {"approved": False, "conviction": round(conv, 4)}

    return {
        "approved": True,
        "strategy_header": "90PCT_SETUP_V9",
        "conviction": round(conv, 4),
        "target_pct": 2.00,
        "stop_pct": 1.50,
        "trailing_stop": True,
        "profit_lock_trig_pct": 0.30,
        "setup_desc": f"Setup_v9 90% Trail Sniper (Conv={conv:.1%}, +2.0% Tgt / +0.30% Trail)",
    }


# --- HEADER 4: [BEST_SETTING_CALL] (Verified >90% Win Rate, 1.0%–1.5% Tgt, -1.0% Fixed SL, NO Trail) ---
def evaluate_best_setting_call(r: dict) -> dict:
    t_str = str(r.get("time", "09:30"))
    if t_str < BEST_15_10_CONFIG["min_time"] or r.get("window") == "AFTER_2PM":
        return {"approved": False, "conviction": 0.0}

    p = r.get("payload", r)
    pro = p.get("pro", {})
    ind = pro.get("indicators", {})
    anat = pro.get("anatomy", {})
    side_str = r.get("side", p.get("side", "BUY"))
    adv_w = float(anat.get("upper_wick_ratio" if side_str == "BUY" else "lower_wick_ratio") or 0.0)

    if int(pro.get("conflict_count") or 0) > BEST_15_10_CONFIG["max_conflicts"]:
        return {"approved": False, "conviction": 0.0}
    if adv_w > BEST_15_10_CONFIG["max_adv_wick"] or float(ind.get("atr14_pct") or 0.0) < BEST_15_10_CONFIG["min_atr"]:
        return {"approved": False, "conviction": 0.0}

    raw = extract_live_34d_features(r)
    z = ((raw - BEST_15_10_MEAN_34) / BEST_15_10_STD_34).astype(np.float16).astype(float)
    z_n = (z / (np.linalg.norm(z) + 1e-9)).astype(np.float16).astype(float)
    z_norm = z_n / (np.linalg.norm(z_n) + 1e-9)

    if len(BEST_15_10_VETO_MAT) > 0:
        if float(np.max(BEST_15_10_VETO_MAT @ z_norm)) >= BEST_15_10_CONFIG["veto_sim_max"]:
            return {"approved": False, "conviction": 0.0}

    sc = float(np.dot(BEST_15_10_WEIGHTS_34, z))
    if len(BEST_15_10_WIN_MAT) > 0:
        mw = float(np.max(BEST_15_10_WIN_MAT @ z_norm))
        if mw >= BEST_15_10_CONFIG["win_sim_min"]:
            sc = max(sc, 1.5) + 4.0 * mw

    conv = round(1.0 / (1.0 + math.exp(-float(np.clip(sc, -15.0, 15.0)))), 6)
    if conv < BEST_15_10_CONFIG["threshold"]:
        return {"approved": False, "conviction": conv}

    return {
        "approved": True,
        "strategy_header": "BEST_SETTING_CALL",
        "conviction": conv,
        "target_pct": 1.50,
        "stop_pct": 1.00,
        "trailing_stop": False,
        "profit_lock_trig_pct": 0.0,
        "setup_desc": f"BEST_SETTING_CALL No-Trail Sniper (Conv={conv:.1%}, Target=+1.50% [1.0–1.5%], SL=-1.00%, NO Trail)",
    }


# ==============================================================================
# RECORDING, LIVE OUTCOME TRACKER & TELEGRAM FORMATTING
# ==============================================================================
def today_str() -> str:
    return datetime.now(TZ).strftime("%Y-%m-%d")


def strategy_signals_sent_today(strategy_header: str) -> int:
    with db_connect() as conn:
        row = conn.execute(
            "SELECT COUNT(*) AS n FROM strategy_calls_log WHERE day=? AND strategy_header=?",
            (today_str(), strategy_header),
        ).fetchone()
        return int(row["n"]) if row else 0


def record_strategy_call(cand: Dict[str, Any], eval_res: Dict[str, Any]) -> bool:
    header = eval_res["strategy_header"]
    day = cand["day"]
    sym = cand["symbol"]
    side = cand["side"]
    entry_p = float(cand["price"])
    tgt_pct = float(eval_res["target_pct"])
    sl_pct = float(eval_res["stop_pct"])
    trail = 1 if eval_res.get("trailing_stop") else 0
    trig = float(eval_res.get("profit_lock_trig_pct") or 0.0)

    stop_p = round(entry_p * (1.0 - sl_pct / 100.0 if side == "BUY" else 1.0 + sl_pct / 100.0), 2)
    tgt_p = round(entry_p * (1.0 + tgt_pct / 100.0 if side == "BUY" else 1.0 - tgt_pct / 100.0), 2)

    # Allow up to 2 calls per strategy per day (and up to 2 on the same stock if >=30m apart)
    with db_connect() as conn:
        cnt = conn.execute(
            "SELECT COUNT(*) AS n FROM strategy_calls_log WHERE day=? AND strategy_header=?",
            (day, header),
        ).fetchone()["n"]
        if cnt >= CFG["MAX_SIGNALS_PER_STRATEGY_DAY"]:
            return False

        existing = conn.execute(
            "SELECT time_ist FROM strategy_calls_log WHERE day=? AND strategy_header=? AND symbol=?",
            (day, header, sym),
        ).fetchall()
        if len(existing) >= 2:
            return False
        for row in existing:
            h1, m1 = [int(x) for x in str(row["time_ist"]).split(":")[:2]]
            h2, m2 = [int(x) for x in str(cand["time"]).split(":")[:2]]
            if abs((h2 * 60 + m2) - (h1 * 60 + m1)) < 30:
                return False

        dedupe = f"{day}|{header}|{sym}|{cand['time']}"
        enriched = dict(cand) | {
            "strategy_header": header,
            "stop": stop_p,
            "target": tgt_p,
            "risk_pct": sl_pct,
            "target_pct": tgt_pct,
            "reward_risk": round(tgt_pct / max(sl_pct, 0.1), 2),
            "trailing_stop": bool(trail),
            "profit_lock_trig_pct": trig,
            "conviction": eval_res["conviction"],
            "setup": eval_res["setup_desc"],
        }
        now_iso = datetime.now(TZ).isoformat()
        try:
            conn.execute(
                """INSERT INTO strategy_calls_log(
                    created_at, day, time_ist, strategy_header, symbol, side,
                    entry_price, stop_price, target_price, stop_pct, target_pct,
                    trailing_stop, profit_lock_trig_pct, conviction, status, payload, dedupe_key
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,'OPEN',?,?)""",
                (
                    now_iso, day, cand["time"], header, sym, side,
                    entry_p, stop_p, tgt_p, sl_pct, tgt_pct,
                    trail, trig, float(eval_res["conviction"]),
                    json.dumps(enriched), dedupe,
                ),
            )
            conn.execute(
                "INSERT INTO signals(created_at,symbol,side,payload,dedupe_key,delivered) VALUES(?,?,?,?,?,0)",
                (now_iso, sym, side, json.dumps(enriched), dedupe),
            )
            conn.commit()
        except sqlite3.IntegrityError:
            return False

    with COMPARISON_JSONL.open("a", encoding="utf-8") as f:
        f.write(json.dumps({
            "event": "SIGNAL_RECORDED",
            "recorded_at": now_iso,
            "day": day,
            "time": cand["time"],
            "strategy_header": header,
            "symbol": sym,
            "side": side,
            "entry": entry_p,
            "stop": stop_p,
            "target": tgt_p,
            "stop_pct": sl_pct,
            "target_pct": tgt_pct,
            "trailing_stop": bool(trail),
            "conviction": eval_res["conviction"],
        }) + "\n")
    return True


def update_live_outcomes(intraday_frames: Dict[str, pd.DataFrame], now: datetime) -> None:
    """Updates MFE/MAE and Target/Stop/EOD status for today's recorded strategy calls."""
    day = today_str()
    with db_connect() as conn:
        open_rows = conn.execute(
            "SELECT * FROM strategy_calls_log WHERE day=? AND status='OPEN'", (day,)
        ).fetchall()

    for row in open_rows:
        sym = row["symbol"]
        df = intraday_frames.get(sym)
        if df is None or df.empty:
            continue
        norm = completed_bars(normalize_intraday(df), now)
        today_bars = norm[[x.strftime("%Y-%m-%d") == day and x.strftime("%H:%M") > str(row["time_ist"]) for x in norm.index]]
        if today_bars.empty:
            continue

        side = row["side"]
        entry = float(row["entry_price"])
        stop_p = float(row["stop_price"])
        tgt_p = float(row["target_price"])
        sl_pct = float(row["stop_pct"])
        tgt_pct = float(row["target_pct"])
        trail = bool(row["trailing_stop"])
        trig = float(row["profit_lock_trig_pct"] or 0.0)

        mfe = float(row["mfe_pct"] or 0.0)
        mae = float(row["mae_pct"] or 0.0)
        status = "OPEN"
        outcome = None
        exit_p = None
        net_ret = None

        for idx, b in today_bars.iterrows():
            hi, lo, cl = float(b["high"]), float(b["low"]), float(b["close"])
            fav = ((hi - entry) / entry * 100.0) if side == "BUY" else ((entry - lo) / entry * 100.0)
            adv = ((entry - lo) / entry * 100.0) if side == "BUY" else ((hi - entry) / entry * 100.0)
            mfe = max(mfe, round(fav, 3))
            mae = max(mae, round(adv, 3))

            if side == "BUY":
                if lo <= stop_p:
                    if trail and mfe >= trig:
                        status, outcome, exit_p, net_ret = "CLOSED", "TRAIL_PROFIT_LOCK", round(entry * (1 + trig / 100.0), 2), round(trig - 0.20, 3)
                    else:
                        status, outcome, exit_p, net_ret = "CLOSED", "STOP_LOSS", stop_p, round(-sl_pct - 0.20, 3)
                    break
                if hi >= tgt_p:
                    status, outcome, exit_p, net_ret = "CLOSED", "TARGET_HIT", tgt_p, round(tgt_pct - 0.20, 3)
                    break
            else:
                if hi >= stop_p:
                    if trail and mfe >= trig:
                        status, outcome, exit_p, net_ret = "CLOSED", "TRAIL_PROFIT_LOCK", round(entry * (1 - trig / 100.0), 2), round(trig - 0.20, 3)
                    else:
                        status, outcome, exit_p, net_ret = "CLOSED", "STOP_LOSS", stop_p, round(-sl_pct - 0.20, 3)
                    break
                if lo <= tgt_p:
                    status, outcome, exit_p, net_ret = "CLOSED", "TARGET_HIT", tgt_p, round(tgt_pct - 0.20, 3)
                    break

            if idx.strftime("%H:%M") >= "15:15":
                raw_r = ((cl - entry) / entry * 100.0) if side == "BUY" else ((entry - cl) / entry * 100.0)
                if trail and mfe >= trig and raw_r < trig:
                    raw_r = trig
                net_ret = round(raw_r - 0.20, 3)
                status = "CLOSED"
                outcome = "EOD_WIN" if net_ret > 0 else "EOD_LOSS"
                exit_p = round(cl, 2)
                break

        with db_connect() as conn:
            conn.execute(
                """UPDATE strategy_calls_log
                   SET status=?, outcome=?, exit_price=?, net_ret_pct=?, mfe_pct=?, mae_pct=?
                   WHERE id=?""",
                (status, outcome, exit_p, net_ret, mfe, mae, row["id"]),
            )
            conn.commit()

        if status == "CLOSED":
            with COMPARISON_JSONL.open("a", encoding="utf-8") as f:
                f.write(json.dumps({
                    "event": "SIGNAL_CLOSED",
                    "closed_at": datetime.now(TZ).isoformat(),
                    "day": day,
                    "strategy_header": row["strategy_header"],
                    "symbol": sym,
                    "side": side,
                    "entry": entry,
                    "exit": exit_p,
                    "outcome": outcome,
                    "net_ret_pct": net_ret,
                    "mfe_pct": mfe,
                    "mae_pct": mae,
                }) + "\n")

            # If LEARNING_SETUP closed, adapt its online weights in SQLite!
            if row["strategy_header"] == "LEARNING_SETUP":
                try:
                    pl = json.loads(row["payload"])
                    x = extract_live_30d_features(pl)
                    w = get_learning_weights()
                    y = 1.0 if (net_ret or 0.0) > 0 else 0.0
                    pred = 1.0 / (1.0 + math.exp(-float(np.clip(np.dot(w, x), -15.0, 15.0))))
                    w = np.clip(w + 0.04 * (y - pred) * x, -3.0, 3.0)
                    state_set("learning_weights_30d", json.dumps([round(float(v), 5) for v in w]))
                except Exception:
                    pass


def format_alert_message(p: Dict[str, Any]) -> str:
    header = p.get("strategy_header", "BEST_SETTING_CALL")
    badge_map = {
        "BEST_SETTING_CALL": "🏆 [BEST_SETTING_CALL — 1.5% TGT / 1.0% SL NO TRAIL]",
        "90PCT_SETUP_V9": "🎯 [90PCT_SETUP_V9 — 2.0% TGT + 0.30% TRAIL]",
        "LEARNING_SETUP": "🧠 [LEARNING_SETUP — ONLINE SELF-LEARNING]",
        "EARLIER_SETUP": "⚡ [EARLIER_SETUP — TOP MOVER 6-PILLAR]",
    }
    header_line = badge_map.get(header, f"📌 [{header}]")
    f = p.get("forecast") or {}
    fline = f"\nKronos (advisory): {f['forecast_change_pct']}% over {f['horizon_bars']} candles" if f.get("forecast_change_pct") is not None else ""
    side = "🟢 BUY (long)" if p["side"] == "BUY" else "🔴 SELL (short, intraday)"
    trail_note = f"Trail Trigger: +{p.get('profit_lock_trig_pct', 0.30):.2f}%" if p.get("trailing_stop") else "NO Trailing Stop (Hard Fixed SL/Target)"
    conv_str = f"{float(p.get('conviction', 0.0)) * 100:.1f}%" if p.get("conviction") else f"{p.get('score', 75)}/100"
    return (
        f"{header_line}\n"
        f"{side} — {p['symbol']}  ({p['day_change_pct']:+.1f}% today | {p.get('time', '')} IST)\n"
        f"Entry ref: ₹{p['price']}  | Prev close: ₹{p['prev_close']}\n"
        f"Stop: ₹{p['stop']} (-{p['risk_pct']}%)  | Target: ₹{p['target']} (+{p.get('target_pct', 1.5)}% | {p['reward_risk']}R)\n"
        f"Exit Mode: {trail_note}\n"
        f"Conviction: {conv_str} | {p.get('setup', '')}\n"
        f"Volume: {p['cumulative_relative_volume']}x cumulative; last candle {p['relative_volume']}x\n"
        f"Traded today: ₹{p['today_turnover_crore']} cr | RSI {p['rsi']} | VWAP ₹{p['vwap']}\n"
        f"Breakout/S&R level: ₹{p['breakout_level']}{fline}\n"
        "Square off before 3:15 PM. Recorded in strategy_calls_log for multi-strategy comparison."
    )


def send_telegram_message(message: str) -> None:
    token = os.getenv("TELEGRAM_BOT_TOKEN", "").strip()
    chat_id = os.getenv("TELEGRAM_CHAT_ID", "").strip()
    if not token or not chat_id:
        raise RuntimeError("Missing TELEGRAM_BOT_TOKEN or TELEGRAM_CHAT_ID GitHub Secret")
    response = requests.post(
        f"https://api.telegram.org/bot{token}/sendMessage",
        json={"chat_id": chat_id, "text": message, "disable_web_page_preview": True},
        timeout=20,
    )
    response.raise_for_status()
    body = response.json()
    if not body.get("ok"):
        raise RuntimeError("Telegram API rejected message: " + str(body.get("description", "unknown error")))


def deliver_pending_signals(limit: int = 8) -> int:
    delivered = 0
    with db_connect() as conn:
        rows = conn.execute(
            "SELECT id,payload FROM signals WHERE delivered=0 ORDER BY id ASC LIMIT ?",
            (max(1, min(int(limit), 20)),),
        ).fetchall()
    for row in rows:
        try:
            payload = json.loads(row["payload"])
            send_telegram_message(format_alert_message(payload))
            with db_connect() as conn:
                conn.execute("UPDATE signals SET delivered=1 WHERE id=?", (row["id"],))
                conn.commit()
            delivered += 1
            LOG.info("Telegram delivered | %s | %s | %s", payload.get("strategy_header"), payload.get("symbol"), payload.get("side"))
        except Exception as exc:
            LOG.exception("Telegram delivery failed for signal id=%s: %s", row["id"], exc)
            break
    return delivered


def once_per_day(key: str) -> bool:
    day = today_str()
    if state_get(key) == day:
        return False
    state_set(key, day)
    return True


def build_scoreboard_summary() -> str:
    with db_connect() as conn:
        rows = conn.execute(
            """SELECT strategy_header,
                      COUNT(*) AS total_calls,
                      SUM(CASE WHEN status='CLOSED' THEN 1 ELSE 0 END) AS closed_calls,
                      SUM(CASE WHEN net_ret_pct > 0 THEN 1 ELSE 0 END) AS wins,
                       COALESCE(SUM(net_ret_pct), 0.0) AS total_net
               FROM strategy_calls_log
               GROUP BY strategy_header"""
        ).fetchall()
    if not rows:
        return "No strategy calls recorded yet."
    lines = ["📊 4-STRATEGY CUMULATIVE SCOREBOARD:"]
    for r in rows:
        closed = int(r["closed_calls"] or 0)
        wins = int(r["wins"] or 0)
        wr = (100.0 * wins / closed) if closed > 0 else 0.0
        lines.append(
            f"• [{r['strategy_header']}]: Calls={r['total_calls']} | Closed={closed} | Wins={wins} ({wr:.1f}%) | Net={float(r['total_net']):+.2f}%"
        )
    return "\n".join(lines)


# ==============================================================================
# MAIN SCAN CYCLE (RUNS ALL 4 HEADERS SIDE-BY-SIDE)
# ==============================================================================
def scan_window_open(now: datetime) -> bool:
    if now.weekday() >= 5:
        return False
    return CFG["ENTRY_START"] <= now.time() <= CFG["ENTRY_END"]


def run_scan_cycle() -> Dict[str, Any]:
    started = time.time()
    now = datetime.now(TZ)
    if not scan_window_open(now):
        return {"status": "outside_entry_window", "at": now.isoformat()}

    if not UNIVERSE_CACHE.exists():
        refresh_liquid_universe(force=True)
    universe = json.loads(UNIVERSE_CACHE.read_text())
    entries = universe.get("scan_symbols", [])
    if not entries:
        raise RuntimeError("Liquid universe cache is empty")
    by_symbol = {e["symbol"]: e for e in entries}
    symbols = [e["symbol"] for e in entries[:CFG["INTRADAY_UNIVERSE_SIZE"]]]

    intraday: Dict[str, pd.DataFrame] = {}
    for off in range(0, len(symbols), CFG["INTRADAY_BATCH_SIZE"]):
        grp = symbols[off:off + CFG["INTRADAY_BATCH_SIZE"]]
        intraday.update(download_batch(grp, CFG["INTRADAY_PERIOD"], CFG["BAR_INTERVAL"]))

    with_data = sum(1 for df in intraday.values() if df is not None and not df.empty)
    cov_pct = round(100.0 * with_data / max(len(symbols), 1), 1)

    if once_per_day("heartbeat_day"):
        try:
            send_telegram_message(
                f"✅ Scout 4-Strategy Multi-Header Engine is LIVE ({now.strftime('%H:%M')} IST).\n"
                f"Active Headers: [BEST_SETTING_CALL], [90PCT_SETUP_V9], [LEARNING_SETUP], [EARLIER_SETUP]\n"
                f"Universe: {len(symbols)} stocks | Data coverage: {cov_pct}%."
            )
        except Exception:
            LOG.exception("heartbeat failed")

    # Build pro candidate payloads across the 200-stock universe
    pro_candidates: List[Dict[str, Any]] = []
    for sym in symbols:
        raw_df = intraday.get(sym, pd.DataFrame())
        if raw_df is None or raw_df.empty:
            continue
        norm_df = completed_bars(normalize_intraday(raw_df), now)
        if len(norm_df) < CFG["MIN_HISTORY_BARS"]:
            continue
        prev_close = float(by_symbol[sym].get("previous_close") or norm_df["close"].iloc[0])
        cand = build_pro_candidate_payload(sym, norm_df, by_symbol[sym], prev_close)
        if cand:
            pro_candidates.append(cand)

    # Evaluate all 4 Strategy Headers side-by-side
    evaluators = [
        ("BEST_SETTING_CALL", evaluate_best_setting_call),
        ("90PCT_SETUP_V9", evaluate_setup_v9),
        ("LEARNING_SETUP", evaluate_learning_setup),
        ("EARLIER_SETUP", evaluate_earlier_setup),
    ]
    queued_by_header: Dict[str, int] = {h: 0 for h, _ in evaluators}

    for header_name, eval_fn in evaluators:
        if strategy_signals_sent_today(header_name) >= CFG["MAX_SIGNALS_PER_STRATEGY_DAY"]:
            continue
        matched: List[Tuple[float, Dict[str, Any], Dict[str, Any]]] = []
        for cand in pro_candidates:
            res = eval_fn(cand)
            if res.get("approved"):
                matched.append((float(res.get("conviction", 0.0)), cand, res))
        matched.sort(key=lambda x: (-x[0], x[1]["time"], x[1]["symbol"]))
        for _, cand, res in matched[:CFG["MAX_SIGNALS_PER_STRATEGY_DAY"]]:
            if record_strategy_call(cand, res):
                queued_by_header[header_name] += 1

    # Update live outcomes for all open calls today
    update_live_outcomes(intraday, now)
    delivered = deliver_pending_signals(limit=8)

    digest_sent = False
    if now.time() >= CFG["DIGEST_AFTER"] and once_per_day("digest_day"):
        scoreboard = build_scoreboard_summary()
        try:
            send_telegram_message(f"📋 Scout Daily Multi-Strategy Digest ({today_str()})\n\n{scoreboard}")
            digest_sent = True
        except Exception:
            LOG.exception("digest failed")

    summary = {
        "status": "complete",
        "at": now.isoformat(),
        "symbols_scanned": len(symbols),
        "coverage_pct": cov_pct,
        "pro_candidates": len(pro_candidates),
        "queued_by_header": queued_by_header,
        "telegram_delivered": delivered,
        "digest_sent": digest_sent,
        "duration_seconds": round(time.time() - started, 1),
    }
    LOG.info("SCAN SUMMARY %s", json.dumps(summary))
    return summary


def run_dry_run_v2() -> Dict[str, Any]:
    init_db()
    if not UNIVERSE_CACHE.exists():
        refresh_liquid_universe(force=True)
    report = {
        "mode": "DRY_RUN_4_STRATEGIES",
        "headers": list(STRATEGY_HEADERS),
        "best_setting_call_config": BEST_15_10_CONFIG,
        "setup_v9_config": LOCKED_GENOME_V9,
        "at_ist": datetime.now(TZ).isoformat(),
    }
    (ROOT / "dry_run_v2_report.json").write_text(json.dumps(report, indent=2), encoding="utf-8")
    LOG.info("DRY RUN SUMMARY %s", json.dumps(report))
    return report


def main() -> int:
    parser = argparse.ArgumentParser(description="Bharat Intraday Scout 2.2 — 4-Strategy Multi-Header Runner")
    parser.add_argument(
        "--task",
        choices=["scan", "reset-today-quota", "dry-run-v2", "refresh-universe", "test-telegram", "test-kronos"],
        default="scan",
    )
    args = parser.parse_args()
    init_db()

    if args.task == "reset-today-quota":
        reset_today_quota()
        return 0
    if args.task == "dry-run-v2":
        run_dry_run_v2()
        return 0
    if args.task == "refresh-universe":
        r = refresh_liquid_universe(force=True)
        LOG.info("UNIVERSE READY | eligible=%s | selected=%s", r.get("eligible_count"), len(r.get("scan_symbols", [])))
        return 0
    if args.task == "test-telegram":
        send_telegram_message(
            "✅ Bharat Intraday Scout 4-Strategy Engine test successful.\n"
            "Active Headers: [BEST_SETTING_CALL], [90PCT_SETUP_V9], [LEARNING_SETUP], [EARLIER_SETUP]"
        )
        return 0
    if args.task == "test-kronos":
        CFG["KRONOS_ENABLED"] = True
        load_kronos()
        return 0

    if CFG["KRONOS_ENABLED"]:
        load_kronos()

    loop_mins = int(CFG.get("CONTINUOUS_LOOP_MINUTES", 0))
    deadline = time.time() + loop_mins * 60 if loop_mins > 0 else time.time()

    while True:
        now = datetime.now(TZ)
        if scan_window_open(now):
            res = run_scan_cycle()
            LOG.info("RUN RESULT %s", json.dumps(res))
        else:
            LOG.info("Outside entry window (%s-%s IST); waiting/exiting", CFG["ENTRY_START"], CFG["ENTRY_END"])
        if time.time() >= deadline or now.time() > CFG["ENTRY_END"]:
            break
        time.sleep(300)

    return 0


if __name__ == "__main__":
    raise SystemExit(main())